export const getAdditionalFields = (formData: FormData): FieldConfig[] => [
  {
    label: 'insight_provider_name',
    value: formData.insightProviderName,
    defaultValue: initialFormData.insightProviderName,
    id: 'insightProviderName',
    className: 'insight-provider-name',
    labelDescription: 'Rendering provider/facility name',
    valueDescription: 'Letters only',
    required: false,
  },
  {
    label: 'insight_provider_npi',
    value: formData.insightProviderNpi,
    defaultValue: initialFormData.insightProviderNpi,
    id: 'insightProviderNpi',
    className: 'insight-provider-npi',
    labelDescription: 'Rendering provider/facility NPI',
    valueDescription: '10 digits',
    required: false,
  },
  {
    label: 'insight_date',
    value: formData.insightDate,
    defaultValue: initialFormData.insightDate,
    id: 'insightDate',
    labelDescription: 'The date of the insight last rendering',
    valueDescription: 'YYYY-MM-DD',
    required: true,
  },
  {
    label: 'insight_source',
    value: formData.insightSource,
    defaultValue: initialFormData.insightSource,
    id: 'insightSource',
    labelDescription: 'The source of the insight',
    valueDescription: '2024 claims',
    required: false,
  },
  {
    label: 'notes',
    value: formData.notes,
    defaultValue: initialFormData.notes,
    id: 'notes',
    labelDescription:
      'Additional information related to the gap, presented in the application upon expation of gap card to see more details',
    valueDescription: 'Up to 250 characters',
  },
  {
    label: 'custom_field_gap_<field_name>',
    value: formData.custom_field_1_value,
    defaultValue: initialFormData.custom_field_1_value,
    id: 'custom_field_1_value',
    labelDescription:
      'Additional custom information on the insight. this field should contain the actual value to present. We will configure together the following: title, type, patient/gap level',
    valueDescription: 'As confgured in the file configurations',
    itemLabel: formData.itemLabels.custom_field_1_value,
    isItemLabelEditable: true,
  },
  {
    label: 'custom_field_patient_<field_name>',
    value: formData.custom_field_2_value,
    defaultValue: initialFormData.custom_field_2_value,
    id: 'custom_field_2_value',
    labelDescription:
      'Additional custom information on the patient. this field should contain the actual value to present. We will configure together the following: title, type, patient/gap level',
    valueDescription: 'As confgured in the file configurations',
    itemLabel: formData.itemLabels.custom_field_2_value,
    isItemLabelEditable: true,
  },
  // Dynamically include additional gap-level custom fields (odd numbers: 3, 5, 7...)
  ...Object.keys(formData)
    .filter((key) => {
      const match = key.match(/^custom_field_(\d+)_value$/);
      if (!match) return false;
      const fieldNumber = Number.parseInt(match[1], 10);
      // Gap fields are odd numbers >= 3 (1 is already handled above)
      return fieldNumber >= 3 && fieldNumber % 2 === 1;
    })
    .map((key) => {
      const value = (formData[key] as string) || '';
      const itemLabel = formData.itemLabels?.[key] || 'Custom field';
      return {
        label: 'custom_field_gap_<field_name>',
        value,
        defaultValue: 'Custom value',
        id: key,
        labelDescription:
          'Additional custom information on the insight. this field should contain the actual value to present. We will configure together the following: title, type, patient/gap level',
        valueDescription: 'As confgured in the file configurations',
        itemLabel,
        isItemLabelEditable: true,
      };
    }),
  // Dynamically include additional patient-level custom fields (even numbers: 4, 6, 8...)
  ...Object.keys(formData)
    .filter((key) => {
      const match = key.match(/^custom_field_(\d+)_value$/);
      if (!match) return false;
      const fieldNumber = Number.parseInt(match[1], 10);
      // Patient fields are even numbers >= 4 (2 is already handled above)
      return fieldNumber >= 4 && fieldNumber % 2 === 0;
    })
    .map((key) => {
      const value = (formData[key] as string) || '';
      const itemLabel = formData.itemLabels?.[key] || 'Custom field';
      return {
        label: 'custom_field_patient_<field_name>',
        value,
        defaultValue: 'Custom value',
        id: key,
        labelDescription:
          'Additional custom information on the patient. this field should contain the actual value to present. We will configure together the following: title, type, patient/gap level',
        valueDescription: 'As confgured in the file configurations',
        itemLabel,
        isItemLabelEditable: true,
      };
    }),
];
