import React, { useState, useCallback, useRef, useEffect } from 'react';
import classNames from 'classnames';
import DataInputField from './DataInputField';
import { Button } from '@getvim/atomic-ui';

interface InputsGroupProps {
  title: string;
  fields: {
    id: string;
    label: string;
    value: string;
    defaultValue: string;
    labelDescription?: string;
    valueDescription?: string;
    disabled?: boolean;
    inputDisabled?: boolean;
    itemLabel?: string;
    isItemLabelEditable?: boolean;
    required?: boolean;
    className?: string;
    selectOptions?: string[];
  }[];
  onInputChange: (fieldId: string, value: string) => void;
  onLabelChange?: (fieldId: string, newLabel: string) => void;
  onAddCustomField?: () => void;
  onAddGapCustomField?: () => void;
}

const InputsGroup: React.FC<InputsGroupProps> = ({
  title,
  fields,
  onInputChange,
  onLabelChange,
  onAddCustomField,
  onAddGapCustomField,
}) => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const previousFieldIdsRef = useRef<Set<string>>(new Set(fields.map((f) => f.id)));

  useEffect(() => {
    const currentFieldIds = new Set(fields.map((f) => f.id));
    const newFieldId = Array.from(currentFieldIds).find(
      (id) => !previousFieldIdsRef.current.has(id),
    );

    if (newFieldId) {
      setIsCollapsed(false);
      setTimeout(() => {
        const input = document.getElementById(`${newFieldId}-input`);
        if (input instanceof HTMLInputElement) {
          input.focus();
          input.select();
        }
      }, 100);
    }

    previousFieldIdsRef.current = currentFieldIds;
  }, [fields]);

  const toggleCollapse = useCallback(() => {
    setIsCollapsed((prev) => !prev);
  }, []);

  const handleInputChange = useCallback(
    (fieldId: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      onInputChange(fieldId, e.target.value);
    },
    [onInputChange],
  );

  const handleLabelChange = useCallback(
    (fieldId: string) => (newLabel: string) => {
      onLabelChange?.(fieldId, newLabel);
    },
    [onLabelChange],
  );

  const handleAddCustomFieldClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onAddCustomField?.();
    },
    [onAddCustomField],
  );

  const handleAddGapCustomFieldClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onAddGapCustomField?.();
    },
    [onAddGapCustomField],
  );

  return (
    <div className={classNames('inputs-group', { 'is-collapsed': isCollapsed })}>
      <div className="input-group-title" onClick={toggleCollapse} style={{ cursor: 'pointer' }}>
        <h2>{title}</h2>
        {onAddGapCustomField && (
          <Button
            buttonType="tinyRounded"
            bgColor="white"
            onClick={handleAddGapCustomFieldClick}
            className="add-custom-field-button"
          >
            <i className="icon-plus" />
            Add gap custom field
          </Button>
        )}
        {onAddCustomField && (
          <Button
            buttonType="tinyRounded"
            bgColor="white"
            onClick={handleAddCustomFieldClick}
            className="add-custom-field-button"
          >
            <i className="icon-plus" />
            Add patient custom field
          </Button>
        )}
        <div className="collapse-icon">
          {isCollapsed ? <i className="icon-chevron-down" /> : <i className="icon-chevron-up" />}
        </div>
      </div>
      <div className="inputs-group-content">
        <div className="inputs-group-inner">
          {fields.map((field) => (
            <DataInputField
              key={field.id}
              label={field.label}
              value={field.value}
              defaultValue={field.defaultValue}
              onChange={handleInputChange(field.id)}
              onLabelChange={onLabelChange ? handleLabelChange(field.id) : undefined}
              id={field.id}
              labelDescription={field.labelDescription || ''}
              valueDescription={field.valueDescription || ''}
              disabled={field.disabled}
              inputDisabled={field.inputDisabled}
              itemLabel={field.itemLabel}
              isItemLabelEditable={field.isItemLabelEditable}
              required={field.required}
              className={classNames(field.className, 'data-input-field')}
              selectOptions={field.selectOptions}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default InputsGroup;
