import React from 'react';

interface InputFieldElementProps {
  selectOptions?: string[];
  value?: string;
  internalValue: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => void;
  id?: string;
  isDisabled: boolean;
  inputDisabled: boolean;
  onBlur: () => void;
  required: boolean;
  showRequiredError: boolean;
}

/**
 * InputFieldElement component handles rendering either a select dropdown or text input
 * based on whether selectOptions are provided.
 */
const InputFieldElement: React.FC<InputFieldElementProps> = ({
  selectOptions,
  value,
  internalValue,
  onChange,
  id,
  isDisabled,
  inputDisabled,
  onBlur,
  required,
  showRequiredError,
}) => {
  if (selectOptions) {
    return (
      <select
        className={`input-field field-value ${showRequiredError ? 'error' : ''}`}
        value={value ?? internalValue}
        onChange={onChange}
        id={`${id}-input`}
        disabled={isDisabled || inputDisabled}
        onBlur={onBlur}
      >
        {!required && <option value="">Select an option</option>}
        {selectOptions.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
      </select>
    );
  }

  return (
    <input
      type="text"
      className={`input-field field-value ${showRequiredError ? 'error' : ''}`}
      value={value ?? internalValue}
      onChange={onChange}
      id={`${id}-input`}
      disabled={isDisabled || inputDisabled}
      onBlur={onBlur}
      placeholder={showRequiredError ? 'Required field' : ''}
    />
  );
};

export default InputFieldElement;
